head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil16406";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil16406.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("endListPage")) + " 페이지) "; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        fn_openPopup();  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_openPopup — as-is 정의 없음(원본 JS 미제공 — 회신)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16406.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name cal_startDate_onblur
 * @description cal_startDate 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal_startDate_onblur = async function(e){
    try {
        await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = ""; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent("cal_startDate"));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16406.cal_startDate_onblur' }); }
};

/**
 * @method
 * @name cal_endDate_onblur
 * @description cal_endDate 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal_endDate_onblur = async function(e){
    try {
        await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = ""; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent("cal_endDate"));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16406.cal_endDate_onblur' }); }
};

/**
 * @method
 * @name rd_period_onclick
 * @description rd_period 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.rd_period_onclick = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.changePeriod('7D',selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16406.rd_period_onclick' }); }
};

/**
 * @method
 * @name btn_searchList_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchList_onclick = async function(e){
    try {
        await scwin.searchList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16406.btn_searchList_onclick' }); }
};

/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_pageSize_onchange = async function(e){
    try {
        scwin.initPageIndex();await scwin.searchList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16406.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name btn_printReceipt_onclick
 * @description 「인쇄」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_printReceipt_onclick = async function(e){
    try {
        await scwin.printReceipt()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16406.btn_printReceipt_onclick' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_85_onclick
 * @description krxpage_pagenavigator_85 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_85_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_loadListReq').set('pageIndex', pi);
        await scwin.tx_load_list();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil16406.krxpage_pagenavigator_85_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchList
 * @description search List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchList = async function () {
    const sbmOptions = {
        id: "tx_fn_searchList",
        method: "post",
        action: "/support/educationFee.do?method=searchEduFeeList",
        ref: "dma_searchListReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_goTab1
 * @description go Tab1 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goTab1 = async function (action) {
    const sbmOptions = {
        id: "tx_fn_goTab1",
        method: "post",
        action: action ?? "/support/educationFee.do",
        ref: "dma_goTab1Req",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_goTab2
 * @description go Tab2 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goTab2 = async function (action) {
    const sbmOptions = {
        id: "tx_fn_goTab2",
        method: "post",
        action: action ?? "/support/educationFee.do",
        ref: "dma_goTab2Req",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/support/educationFee.do?method=searchEduFeeList",
        ref: "dma_loadListReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_85").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPageIndex
 * @description init Page Index 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPageIndex = function () {
    $c.util.getComponent('dma_searchListReq').set('pageIndex', "1");
};

/**
 * @method
 * @name tx_fn_goPrint
 * @description go Print 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goPrint = async function () {
    try { return await $c.data.downFile("/common/newPrint.do", "", ($c.util.getComponent("dma_goPrintReq") ? $c.util.getComponent("dma_goPrintReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name searchList
 * @description search List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchList = async function () {
    if ($c.util.getComponent('cal_startDate').getValue()> $c.util.getComponent('cal_endDate').getValue()) {
        await $c.win.alert('시작일이 종료일보다 이후 일자 입니다.');
        return;
    }
    $c.util.getComponent('dma_searchListReq').set('method', "searchEduFeeList");
    await scwin.tx_fn_searchList();
};

/**
 * @method
 * @name printReceipt
 * @description print Receipt 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.printReceipt = async function () {
    const frm = (document.eduFeeReceiptForm || { elements: [] });
    let cnt = 0;
    let seq = 0;
    let isurCd = "";
    const rcvDd = "";
    if (frm.checkType) {
        if (frm.checkType.length) {
            for (let i = 0; i < frm.checkType.length; i++) {
                if (frm.checkType[i].checked) {
                    cnt = cnt + 1;
                    seq = frm.checkType[i].value;
                    isurCd = frm.isurCd[i].value;
                }
            }
        } else {
            if ($c.util.getComponent("dma_searchListReq").get("checkType")) {
                cnt = cnt + 1;
                seq = $c.util.getComponent("dma_searchListReq").get("checkType");
                isurCd = $c.util.getComponent("dma_searchListReq").get("isurCd");
            }
        }
    }
    if (cnt === 1) {
        scwin.goPrint(seq, isurCd);
    } else {
        await $c.win.alert("영수증발급 대상을 1개 체크후 인쇄를 누르세요.");
        return;
    }
};

/**
 * @method
 * @name goPrint
 * @description go Print 처리
 * @param {*} seq seq
 * @param {String} isurCd isurCd
 * @returns {void}
 * @hidden N
 */
scwin.goPrint = function (seq, isurCd) {
    const rexName = "RLDFIL00032";
    const dataLocation = "/outer/reportPrint.do?method=searchEduFeeNewReport&isurCd=" + isurCd + "&seq=" + seq;
    $.ajax({ type: "POST", async: false, url: dataLocation, data: {  }, success: async function(data) {
                const result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                $c.util.getComponent('dma_searchListReq').set('ncomNm', result.comNm);
                $c.util.getComponent('dma_searchListReq').set('ndisclsEduCostDepoDd', result.disclsEduCostDepoDd);
                $c.util.getComponent('dma_searchListReq').set('ndisclsEduApplAmt', result.disclsEduApplAmt);
                if (result.disclsEduApplAmt1) {
                    $c.util.getComponent('dma_searchListReq').set('ndisclsEduApplAmt1', result.disclsEduApplAmt1);
                }
                if (result.disclsEduApplAmt2) {
                    $c.util.getComponent('dma_searchListReq').set('ndisclsEduApplAmt2', result.disclsEduApplAmt2);
                }
                if (result.disclsEduApplAmt3) {
                    $c.util.getComponent('dma_searchListReq').set('ndisclsEduApplAmt3', result.disclsEduApplAmt3);
                }
                if (result.disclsEduApplAmt4) {
                    $c.util.getComponent('dma_searchListReq').set('ndisclsEduApplAmt4', result.disclsEduApplAmt4);
                }
                if (result.disclsEduApplAmt5) {
                    $c.util.getComponent('dma_searchListReq').set('ndisclsEduApplAmt5', result.disclsEduApplAmt5);
                }
                if (result.disclsEduApplAmt6) {
                    $c.util.getComponent('dma_searchListReq').set('ndisclsEduApplAmt6', result.disclsEduApplAmt6);
                }
                if (result.disclsEduApplAmt7) {
                    $c.util.getComponent('dma_searchListReq').set('ndisclsEduApplAmt7', result.disclsEduApplAmt7);
                }
                if (result.disclsEduApplAmt8) {
                    $c.util.getComponent('dma_searchListReq').set('ndisclsEduApplAmt8', result.disclsEduApplAmt8);
                }
                if (result.disclsEduApplAmt9) {
                    $c.util.getComponent('dma_searchListReq').set('ndisclsEduApplAmt9', result.disclsEduApplAmt9);
                }
                $c.util.getComponent('dma_searchListReq').set('nTempleteCd', rexName);
                await scwin.tx_fn_goPrint();
            }, error: async function(request, status, error) {
                await $c.win.alert("장애발생.");
                return;
            }, complete: function() {

            } });
};

/**
 * @method
 * @name changePeriod
 * @description change Period 처리
 * @param {*} type type
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.changePeriod = function (type, obj) {
    const startDate = ($c.util.getComponent('cal_startDate') || $c.util.getComponent('ipt_startDate') || $c.util.getComponent('startDate'));
    const endDate = ($c.util.getComponent('cal_endDate') || $c.util.getComponent('ipt_endDate') || $c.util.getComponent('endDate'));
    const ie = null;
    switch (type) {
        case '7D':
        scwin.setDate(7, startDate, endDate, ie);
        break;
        case '1M':
        scwin.setMonth(1, startDate, endDate, ie);
        break;
        case '1Y':
        scwin.setFullYear(1, startDate, endDate, ie);
        break;
        case '2Y':
        scwin.setFullYear(2, startDate, endDate, ie);
        break;
    }
};

/**
 * @method
 * @name setDate
 * @description set Date 처리
 * @param {String} pNewDd pNewDd
 * @param {*} startDate startDate
 * @param {*} endDate endDate
 * @param {*} ie ie
 * @returns {void}
 * @hidden N
 */
scwin.setDate = function (pNewDd, startDate, endDate, ie) {
    let vDate, vDate2, vMon2, vMon, vDay2, vDay;
    vDate = new Date();
    vDate2 = new Date();
    vDate.setDate(vDate.getDate());
    vDate2.setDate(vDate.getDate() - pNewDd);
    if ((vDate2.getMonth() + 1) < 10) {
        vMon2 = "0" + String(vDate2.getMonth() + 1);
    } else {
        vMon2 = String(vDate2.getMonth() + 1);
    }
    if ((vDate.getMonth() + 1) < 10) {
        vMon = "0" + String(vDate.getMonth() + 1);
    } else {
        vMon = String(vDate.getMonth() + 1);
    }
    if (vDate2.getDate() < 10) {
        vDay2 = "0" + String(vDate2.getDate());
    } else {
        vDay2 = String(vDate2.getDate());
    }
    if (vDate.getDate() < 10) {
        vDay = "0" + String(vDate.getDate());
    } else {
        vDay = String(vDate.getDate());
    }
    $c.util.getComponent("cal_startDate").setValue(String(vDate2.getFullYear()) + String(vMon2) + String(vDay2));
    $c.util.getComponent("cal_endDate").setValue(String(vDate.getFullYear()) + String(vMon) + String(vDay));
};

/**
 * @method
 * @name setMonth
 * @description set Month 처리
 * @param {*} pNewmonth pNewmonth
 * @param {*} startDate startDate
 * @param {*} endDate endDate
 * @param {*} ie ie
 * @returns {void}
 * @hidden N
 */
scwin.setMonth = function (pNewmonth, startDate, endDate, ie) {
    let vDate, vDate2, vMon2, vMon, vDay2, vDay;
    vDate = new Date();
    vDate2 = new Date();
    vDate.setMonth(vDate.getMonth());
    vDate2.setMonth(vDate.getMonth() - pNewmonth);
    if ((vDate2.getMonth() + 1) < 10) {
        vMon2 = "0" + String(vDate2.getMonth() + 1);
    } else {
        vMon2 = String(vDate2.getMonth() + 1);
    }
    if ((vDate.getMonth() + 1) < 10) {
        vMon = "0" + String(vDate.getMonth() + 1);
    } else {
        vMon = String(vDate.getMonth() + 1);
    }
    if (vDate2.getDate() < 10) {
        vDay2 = "0" + String(vDate2.getDate());
    } else {
        vDay2 = String(vDate2.getDate());
    }
    if (vDate.getDate() < 10) {
        vDay = "0" + String(vDate.getDate());
    } else {
        vDay = String(vDate.getDate());
    }
    $c.util.getComponent("cal_startDate").setValue(String(vDate2.getFullYear()) + String(vMon2) + String(vDay2));
    $c.util.getComponent("cal_endDate").setValue(String(vDate.getFullYear()) + String(vMon) + String(vDay));
};

/**
 * @method
 * @name setFullYear
 * @description set Full Year 처리
 * @param {*} pNewyear pNewyear
 * @param {*} startDate startDate
 * @param {*} endDate endDate
 * @param {*} ie ie
 * @returns {void}
 * @hidden N
 */
scwin.setFullYear = function (pNewyear, startDate, endDate, ie) {
    let vDate, vDate2, vMon2, vMon, vDay2, vDay;
    vDate = new Date();
    vDate2 = new Date();
    if (!ie) {
        vDate.setFullYear(vDate.getFullYear());
        vDate2.setFullYear(vDate.getFullYear() - pNewyear);
    } else {
        vDate.setFullYear(vDate.getFullYear());
        vDate2.setFullYear(vDate.getFullYear() - pNewyear);
    }
    if ((vDate2.getMonth() + 1) < 10) {
        vMon2 = "0" + String(vDate2.getMonth() + 1);
    } else {
        vMon2 = String(vDate2.getMonth() + 1);
    }
    if ((vDate.getMonth() + 1) < 10) {
        vMon = "0" + String(vDate.getMonth() + 1);
    } else {
        vMon = String(vDate.getMonth() + 1);
    }
    if (vDate2.getDate() < 10) {
        vDay2 = "0" + String(vDate2.getDate());
    } else {
        vDay2 = String(vDate2.getDate());
    }
    if (vDate.getDate() < 10) {
        vDay = "0" + String(vDate.getDate());
    } else {
        vDay = String(vDate.getDate());
    }
    $c.util.getComponent("cal_startDate").setValue(String(vDate2.getFullYear()) + String(vMon2) + String(vDay2));
    $c.util.getComponent("cal_endDate").setValue(String(vDate.getFullYear()) + String(vMon) + String(vDay));
};

/**
